"use client";

// spec/004_card_movement_archive_restore.md § 画面（アーカイブ／削除の一覧と復元）
import { useState } from "react";
import { useRouter } from "next/navigation";

type Card = { id: string; listId: string; title: string };
type ListRef = { id: string; title: string };

export default function ArchivePanel({ lists }: { lists: ListRef[] }) {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [archived, setArchived] = useState<Card[]>([]);
  const [deleted, setDeleted] = useState<Card[]>([]);

  async function load() {
    const arch: Card[] = [];
    const del: Card[] = [];
    for (const l of lists) {
      const a = await fetch(`/api/lists/${l.id}/cards?status=archived`)
        .then((r) => r.json())
        .catch(() => ({ items: [] }));
      const d = await fetch(`/api/lists/${l.id}/cards?status=deleted`)
        .then((r) => r.json())
        .catch(() => ({ items: [] }));
      arch.push(...(a.items ?? []));
      del.push(...(d.items ?? []));
    }
    setArchived(arch);
    setDeleted(del);
  }

  async function toggle() {
    const next = !open;
    setOpen(next);
    if (next) await load();
  }

  async function act(url: string, method: string) {
    await fetch(url, { method });
    await load();
    router.refresh();
  }

  return (
    <div className="mt-6">
      <button
        type="button"
        onClick={toggle}
        className="rounded border border-slate-300 px-3 py-1.5 text-sm text-slate-700 hover:bg-slate-100"
      >
        {open ? "アーカイブ／ゴミ箱を閉じる" : "アーカイブ／ゴミ箱を表示"}
      </button>

      {open && (
        <div className="mt-3 grid grid-cols-1 gap-4 sm:grid-cols-2">
          <section className="rounded-lg border border-slate-200 bg-white p-4">
            <h3 className="mb-2 text-sm font-semibold text-slate-700">
              アーカイブ済み（{archived.length}）
            </h3>
            {archived.length === 0 ? (
              <p className="text-xs text-slate-400">なし</p>
            ) : (
              <ul className="flex flex-col gap-2">
                {archived.map((c) => (
                  <li
                    key={c.id}
                    className="flex items-center justify-between gap-2 rounded border border-slate-200 px-2 py-1 text-sm"
                  >
                    <span className="truncate">{c.title}</span>
                    <button
                      type="button"
                      onClick={() => act(`/api/cards/${c.id}/unarchive`, "POST")}
                      className="shrink-0 rounded border border-slate-300 px-2 py-0.5 text-xs text-slate-700 hover:bg-slate-100"
                    >
                      復元
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </section>

          <section className="rounded-lg border border-slate-200 bg-white p-4">
            <h3 className="mb-2 text-sm font-semibold text-slate-700">
              ゴミ箱（{deleted.length}）
            </h3>
            {deleted.length === 0 ? (
              <p className="text-xs text-slate-400">なし</p>
            ) : (
              <ul className="flex flex-col gap-2">
                {deleted.map((c) => (
                  <li
                    key={c.id}
                    className="flex items-center justify-between gap-2 rounded border border-slate-200 px-2 py-1 text-sm"
                  >
                    <span className="truncate">{c.title}</span>
                    <div className="flex shrink-0 gap-1">
                      <button
                        type="button"
                        onClick={() => act(`/api/cards/${c.id}/restore`, "POST")}
                        className="rounded border border-slate-300 px-2 py-0.5 text-xs text-slate-700 hover:bg-slate-100"
                      >
                        復元
                      </button>
                      <button
                        type="button"
                        onClick={() => act(`/api/cards/${c.id}/purge`, "DELETE")}
                        className="rounded border border-red-300 px-2 py-0.5 text-xs text-red-700 hover:bg-red-50"
                      >
                        完全削除
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

